def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)] sorted by price desc, then arrival asc
    sell_book = []  # [(price, arrival_time, id, qty)] sorted by price asc, then arrival asc
    order_map = {}  # id -> (side, price, arrival_time) for tracking resting orders
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_time = order_map[cancel_id]
                del order_map[cancel_id]

                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != cancel_id]

        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            remaining_qty = qty

            if side == 'buy':
                # Match against sell book
                new_sell_book = []
                for sell_price, sell_arr_time, sell_id, sell_qty in sell_book:
                    if remaining_qty == 0:
                        new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))
                        continue

                    # Check if this sell matches (market orders match any price, limit orders match at or below)
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty > 0:
                            new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))
                        else:
                            if sell_id in order_map:
                                del order_map[sell_id]
                    else:
                        new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))

                sell_book = new_sell_book

                # Add to buy book if limit order with remaining qty or market with remaining qty that is limit
                if remaining_qty > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('buy', price, arrival_time)
                    # Resort buy book: highest price first, then earliest arrival
                    buy_book.sort(key=lambda x: (-x[0], x[1]))

            else:  # side == 'sell'
                # Match against buy book
                new_buy_book = []
                for buy_price, buy_arr_time, buy_id, buy_qty in buy_book:
                    if remaining_qty == 0:
                        new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))
                        continue

                    # Check if this buy matches (market orders match any price, limit orders match at or above)
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_qty -= trade_qty

                        if buy_qty > 0:
                            new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))
                        else:
                            if buy_id in order_map:
                                del order_map[buy_id]
                    else:
                        new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))

                buy_book = new_buy_book

                # Add to sell book if limit order with remaining qty
                if remaining_qty > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('sell', price, arrival_time)
                    # Resort sell book: lowest price first, then earliest arrival
                    sell_book.sort(key=lambda x: (x[0], x[1]))

    return trades

